--region handler
---跳转按钮点击回调
function ActivityClayFigureNode:JumpButtonOnClickHandler()
    if checkString(self._activityDojo.link) ~= '' then
        xTry(function()
            local isOther = 1
            if UIModule.CurrentScreen then
                local dialog = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.UIActivityMainDialog)
                if dialog and dialog.Env and dialog.Env._displayType ~= nil then
                    isOther = 0
                    ---社群类型
                    xRecord.record('6-010', string.format("click_community_enter_%d", checkInt(self._activityDojo.id)))
                end
            end
            if isOther == 1 then
                xRecord.record('6-005', string.format('enter_activity_page_%d', checkInt(self._activityDojo.id)))
            end
        end)
        ---@type SDKService
        local SDKService = import('Game.Entry.SDKService')
        local link = self._activityDojo.link
        if SDKService:GetInstance():IsCommonSDK() then
            ---@type UserComponent
            local userComponent =  GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
            if  isNotNull(userComponent) then
                link = string.gsub(link, "{$accessToken}", userComponent.userInfo.access_token)
            end
        else 
            link = string.gsub(link, "{$accessToken}", "") 
        end
        local go = GameUtils.GetRedPointGo(self.ButtonGroup.transform:Find("Imgbg"))
        CfUtils.SetActive(go, false)
        local ActivityUtils = import('Game.Activity.ActivityUtils')
        ActivityUtils.UpdateActivityMainRedPointState(self._activityDojo.id, -1)
        GameUtils.Request("Activity2/linkClick", {activityUuid = self._activityDojo.id}, function(request, response)
        end)
        CfUtils.OpenURL(link)
    else
        GameUtils.Toast(localize("跳转失败"))
    end
end
--endregion handler

