---刷新自身
---@param activityDojo ActivityDojo
function ActivityClayFigureNode:Refresh(activityDojo)
    self._activityDojo = activityDojo
    KTool.SetActive(self.ButtonGroup, checkString(activityDojo.link) ~= '')
    local go = GameUtils.GetRedPointGo(self.ButtonGroup.transform:Find("Imgbg"))
    CfUtils.SetActive(go, checkNumber(self._activityDojo.redDotHint) == 0)
end
--endregion public

return ActivityClayFigureNode